repair.ListActiveAssetTypes.sql:
SELECT id, key, name, code_prefix, icon, mount FROM platform.asset_types
WHERE is_active
ORDER BY sort_order, name;

repair.AssetCodeTaken.sql:
SELECT EXISTS (
    SELECT 1 FROM platform.assets WHERE lower(code) = lower($1) AND id <> $2
);

repair.InsertAsset.sql:
INSERT INTO platform.assets (id, code, name, asset_type_id, room_id, pos_x, pos_z, rotation_deg, created_by, updated_by)
VALUES ($1, $2, $3, $4, $5, $6::float8, $7::float8,
    $8, $9, $9);

repair.ListContractorTypes.sql:
SELECT id, name FROM repair.contractor_types
WHERE is_active
ORDER BY lower(name);

repair.InsertContractorType.sql:
INSERT INTO repair.contractor_types (name, created_by_id) VALUES ($1, $2)
ON CONFLICT ((lower(name))) DO NOTHING
RETURNING id, name;

repair.UpdateContractor.sql:
UPDATE repair.contractors
SET name = $1, contact_name = $2, phone = $3, note = $4, is_active = $5, updated_at = now()
WHERE id = $6;

repair.ListActiveCategories.sql:
SELECT id, name, icon, default_priority, is_other FROM repair.categories
WHERE is_active
ORDER BY is_other, sort_order, name;

repair.ListCategoryBuildingTypes.sql:
SELECT cbt.category_id, cbt.building_type_id FROM repair.category_building_types cbt
JOIN platform.building_types bt ON bt.id = cbt.building_type_id AND bt.is_active
ORDER BY cbt.category_id, bt.sort_order, bt.name;

repair.ListActiveRooms.sql:
SELECT r.id, r.floor_id, r.name, r.area_type FROM platform.rooms r
WHERE r.is_active
ORDER BY r.sort_order, r.name;

repair.LockActiveCategory.sql:
SELECT default_priority, is_other FROM repair.categories
WHERE id = $1 AND is_active
FOR NO KEY UPDATE;

repair.ActiveFloorInBuilding.sql:
SELECT EXISTS (
    SELECT 1 FROM platform.floors f
    JOIN platform.buildings b ON b.id = f.building_id
    WHERE f.id = $1 AND f.building_id = $2 AND f.is_active AND b.is_active
);

repair.ActiveRoomOnFloor.sql:
SELECT EXISTS (
    SELECT 1 FROM platform.rooms r
    WHERE r.id = $1 AND r.floor_id = $2 AND r.is_active
);

repair.CategoryUsedInBuilding.sql:
SELECT EXISTS (
    SELECT 1 FROM platform.buildings b
    JOIN repair.category_building_types cbt ON cbt.building_type_id = b.building_type_id
    WHERE b.id = $1 AND cbt.category_id = $2
);

repair.NextTicketCounter.sql:
INSERT INTO repair.ticket_counters (year, last_no) VALUES ($1, 1)
ON CONFLICT (year) DO UPDATE SET last_no = repair.ticket_counters.last_no + 1, updated_at = now()
RETURNING last_no;

repair.LockAttachablePhotos.sql:
SELECT id FROM repair.photos
WHERE id = ANY($1::uuid[]) AND uploader_id = $2 AND attached_at IS NULL AND created_at > $3
FOR UPDATE;

repair.InsertTicketPhotos.sql:
INSERT INTO repair.ticket_photos (photo_id, ticket_id, kind, event_id, sort_order)
SELECT p.photo_id, $1, $2, $3::uuid, p.ord::integer - 1
FROM unnest($4::uuid[]) WITH ORDINALITY AS p (photo_id, ord);

repair.ListTicketPhotos.sql:
SELECT photo_id, kind, event_id FROM repair.ticket_photos
WHERE ticket_id = $1
ORDER BY kind, sort_order;

repair.DeleteUnattachedPhotos.sql:
DELETE FROM repair.photos
WHERE attached_at IS NULL AND created_at < $1
RETURNING storage_key, thumb_key;

repair.AdminLockCategory.sql:
SELECT c.id, c.name, c.icon, c.sort_order, c.is_active, c.default_priority, c.is_other, c.updated_at,
       (EXISTS (SELECT 1 FROM repair.tickets t WHERE t.category_id = c.id))::boolean AS in_use
FROM repair.categories c WHERE c.id = $1 FOR UPDATE;

repair.AdminUpdateCategory.sql:
UPDATE repair.categories SET name = $1, icon = $2, default_priority = $3, is_active = $4,
    updated_by_id = $5, updated_at = now()
WHERE id = $6;

repair.AdminInsertCategoryBuildingTypes.sql:
INSERT INTO repair.category_building_types (category_id, building_type_id)
SELECT $1, unnest($2::uuid[])
ON CONFLICT DO NOTHING;

repair.AdminClearCategoryActiveBuildingT.sql:
DELETE FROM repair.category_building_types cbt
USING platform.building_types bt
WHERE cbt.category_id = $1 AND bt.id = cbt.building_type_id AND bt.is_active;

repair.AdminLinkBuildingTypeCategories.sql:
INSERT INTO repair.category_building_types (category_id, building_type_id)
SELECT unnest($1::uuid[]), $2
ON CONFLICT DO NOTHING;

repair.AdminInsertSymptom.sql:
INSERT INTO repair.symptoms (id, category_id, name, priority, sort_order, updated_by_id)
VALUES ($1, $2, $3, $4,
        (SELECT coalesce(max(sort_order), 0) + 1 FROM repair.symptoms WHERE category_id = $2), $5);

repair.AdminLockContractorType.sql:
SELECT t.id, t.name, t.is_active, t.updated_at,
       (EXISTS (SELECT 1 FROM repair.contractor_type_links l WHERE l.type_id = t.id))::boolean AS in_use
FROM repair.contractor_types t WHERE t.id = $1 FOR UPDATE;

repair.InsertTicket.sql:
INSERT INTO repair.tickets (
    id, ticket_no, status, closed_reason, closed_at, priority, priority_source, category_id, category_other, symptom_other,
    building_id, floor_id, room_id, location_detail, details, asset_code, asset_id, reporter_id, created_at, updated_at
) VALUES (
    $1, $2, $3, $4::text, $5::timestamptz,
    $6, $7, $8::uuid,
    $9::text, $10::text,
    $11, $12, $13, $14, $15, $16, $17::uuid,
    $18, $19, $19
);

repair.InsertTicketSymptoms.sql:
INSERT INTO repair.ticket_symptoms (ticket_id, symptom_id, sort_order)
SELECT $1, s.symptom_id, s.ord::integer - 1
FROM unnest($2::uuid[]) WITH ORDINALITY AS s (symptom_id, ord);

repair.FirstReportPhotos.sql:
SELECT DISTINCT ON (ticket_id) ticket_id, photo_id FROM repair.ticket_photos
WHERE ticket_id = ANY($1::uuid[]) AND kind = 'report'
ORDER BY ticket_id, sort_order;

repair.LockTicket.sql:
SELECT id, status, closed_reason, reporter_id, expected_done_on, work_by, contractor_id, contractor_rating, send_back_count FROM repair.tickets
WHERE id = $1
FOR UPDATE;

repair.AdminCloseTicket.sql:
UPDATE repair.tickets
SET status = 'closed', closed_reason = 'admin_closed', closed_at = $1, auto_close_at = NULL, updated_at = $1
WHERE id = $2;

repair.SendBackTicket.sql:
UPDATE repair.tickets
SET status = 'in_progress', send_back_count = send_back_count + 1, auto_close_at = NULL, updated_at = $1
WHERE id = $2;

repair.HandOverTicket.sql:
UPDATE repair.tickets
SET status = 'in_progress', closed_reason = NULL, closed_at = NULL, updated_at = $1
WHERE id = $2;

repair.InsertSubscriber.sql:
INSERT INTO repair.ticket_subscribers (ticket_id, user_id, created_at, updated_at)
VALUES ($1, $2, $3, $3)
ON CONFLICT (ticket_id, user_id) DO NOTHING;

platform.InsertAssetType.sql:
INSERT INTO platform.asset_types (id, key, name, code_prefix, icon, mount, sort_order, updated_by_id)
VALUES ($1, $2, $3, $4, $5, $6,
        (SELECT coalesce(max(sort_order), 0) + 1 FROM platform.asset_types), $7);

platform.UpdateAssetType.sql:
UPDATE platform.asset_types SET name = $1, code_prefix = $2, icon = $3, mount = $4,
    updated_by_id = $5, updated_at = now()
WHERE id = $6;

platform.LockBuilding.sql:
SELECT b.id, b.name, b.updated_at, b.building_type_id, bt.name AS building_type_name
FROM platform.buildings b JOIN platform.building_types bt ON bt.id = b.building_type_id
WHERE b.id = $1 AND b.is_active FOR UPDATE OF b;

platform.LockBuildingType.sql:
SELECT t.id, t.name, t.is_active, t.updated_at,
       (EXISTS (SELECT 1 FROM platform.buildings b WHERE b.building_type_id = t.id AND b.is_active))::boolean AS in_use
FROM platform.building_types t WHERE t.id = $1 FOR UPDATE;

platform.InsertRole.sql:
INSERT INTO platform.roles (key, name, description, created_by_id, updated_by_id)
VALUES ($1, $2, $3, $4, $4)
RETURNING *;

platform.CountRealUsersInRole.sql:
SELECT count(*)::bigint FROM platform.users u
LEFT JOIN platform.user_roles ur ON ur.employee_code = u.employee_code
WHERE NOT u.is_demo AND (ur.role_id = $1 OR (ur.role_id IS NULL AND $2::text = 'employee'));

platform.CreateSession.sql:
INSERT INTO platform.sessions (token_hash, user_id, origin_user_id, expires_at)
VALUES ($1, $2, $3, $4)
RETURNING *;

platform.UpsertUserRole.sql:
INSERT INTO platform.user_roles (employee_code, role_id)
SELECT $1, r.id FROM platform.roles r WHERE r.key = $2
ON CONFLICT (employee_code) DO UPDATE SET role_id = EXCLUDED.role_id, updated_at = now();

platform.SetUserRole.sql:
INSERT INTO platform.user_roles (employee_code, role_id)
VALUES ($1, $2)
ON CONFLICT (employee_code) DO UPDATE SET role_id = EXCLUDED.role_id, updated_at = now();
